            if p == goal:
                return path
            for action, (dr, dc) in DIRS.items():
                n = (p[0]+dr, p[1]+dc)
                footprint = {n, (n[0]+offset[0], n[1]+offset[1])} if offset else {n}
                if n not in seen and footprint <= floor and not footprint & obstacles:
